"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { Checkbox } from "@/components/ui/checkbox";

import {
  ArrowLeft,
  User,
  Mail,
  Shield,
  Lock,
  Eye,
  EyeOff,
  Save,
  Loader2,
  CheckCircle2,
} from "lucide-react";

import { useToast } from "@/hooks/use-toast";


import { createUser } from "@/lib/api/user";

interface CreateUserForm {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  role: string;
  status: string;
}

export default function CreateUserPage() {
  const router = useRouter();
  const { toast } = useToast();

  const [loading, setLoading] = useState(false);

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] =
    useState(false);

  const [errors, setErrors] = useState<
    Partial<Record<keyof CreateUserForm, string>>
  >({});

  const [formData, setFormData] = useState<CreateUserForm>({
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
    role: "USER",
    status: "ACTIVE",
  });

  //---------------------------------------------------
  // Handle Input Change
  //---------------------------------------------------

  const handleInputChange = (
    field: keyof CreateUserForm,
    value: string | boolean
  ) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));

    if (errors[field]) {
      setErrors((prev) => ({
        ...prev,
        [field]: "",
      }));
    }
  };

  //---------------------------------------------------
  // Email Validation
  //---------------------------------------------------

  const validateEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  //---------------------------------------------------
  // Form Validation
  //---------------------------------------------------

  const validateForm = () => {
    const newErrors: Partial<Record<keyof CreateUserForm, string>> =
      {};

    if (!formData.name.trim()) {
      newErrors.name = "Name is required";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!validateEmail(formData.email)) {
      newErrors.email = "Invalid email";
    }

    if (!formData.password) {
      newErrors.password = "Password is required";
    } else if (formData.password.length < 8) {
      newErrors.password =
        "Password must be at least 8 characters";
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword =
        "Confirm your password";
    }

    if (
      formData.password &&
      formData.confirmPassword &&
      formData.password !== formData.confirmPassword
    ) {
      newErrors.confirmPassword =
        "Passwords do not match";
    }

    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  };

  //---------------------------------------------------
  // Submit
  //---------------------------------------------------

  const handleSubmit = async (
    e: React.FormEvent<HTMLFormElement>
  ) => {
    e.preventDefault();

    if (!validateForm()) {
      toast({
        title: "Validation Error",
        description:
          "Please correct the highlighted fields.",
        variant: "destructive",
      });

      return;
    }

    setLoading(true);

    try {
      // API Integration in Part 4

      console.log(formData);

      toast({
        title: "Success",
        description:
          "User created successfully.",
      });

      router.push("/users");
    } catch (error) {
      toast({
        title: "Error",
        description:
          "Unable to create user.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  //---------------------------------------------------
  // Page Starts Here
  //---------------------------------------------------

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">

        {/* Back Button */}

        <Link
          href="/users"
          className="mb-6 inline-flex items-center gap-2 text-gray-400 hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Users
        </Link>

        {/* Form Starts */}

        <form onSubmit={handleSubmit}>
                  {/* Header */}

          <div className="mb-8 flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <div className="flex items-center gap-3">
                <div className="rounded-xl bg-[#2563EB]/20 p-3">
                  <User className="h-7 w-7 text-[#4A9FD4]" />
                </div>

                <div>
                  <h1 className="text-3xl font-semibold text-[#4A9FD4]">
                    Create User
                  </h1>

                  <p className="mt-1 text-sm text-gray-400">
                    Add a new user and assign permissions for the Command
                    Center.
                  </p>
                </div>
              </div>
            </div>

            <div className="flex gap-3">
              <Button
                type="button"
                variant="outline"
                className="border-[#444] bg-transparent text-white hover:bg-[#333]"
                onClick={() => router.push("/users")}
              >
                Cancel
              </Button>

              <Button
                type="submit"
                disabled={loading}
                className="gap-2 bg-[#2563EB] text-white hover:bg-[#1D4ED8]"
              >
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4" />
                    Create User
                  </>
                )}
              </Button>
            </div>
          </div>

          {/* ======================================================== */}
          {/* Summary Cards */}
          {/* ======================================================== */}

          <div className="mb-8 grid gap-4 md:grid-cols-2 xl:grid-cols-4">

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-blue-500/20 p-3">
                  <User className="h-6 w-6 text-blue-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">
                    Full Name
                  </p>

                  <p className="truncate text-lg font-semibold text-white">
                    {formData.name || "--"}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-green-500/20 p-3">
                  <Mail className="h-6 w-6 text-green-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">
                    Email
                  </p>

                  <p className="truncate text-lg font-semibold text-white">
                    {formData.email || "--"}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-purple-500/20 p-3">
                  <Shield className="h-6 w-6 text-purple-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">
                    Role
                  </p>

                  <p className="text-lg font-semibold text-white">
                    {formData.role}
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card className="border-[#333] bg-[#222]">
              <CardContent className="flex items-center gap-4 p-5">
                <div className="rounded-full bg-emerald-500/20 p-3">
                  <CheckCircle2 className="h-6 w-6 text-emerald-500" />
                </div>

                <div>
                  <p className="text-sm text-gray-400">
                    Status
                  </p>

                  <p className="text-lg font-semibold text-white">
                    {formData.status}
                  </p>
                </div>
              </CardContent>
            </Card>

          </div>

          {/* ======================================================== */}
          {/* Main Grid */}
          {/* ======================================================== */}

          <div className="grid gap-6 lg:grid-cols-2">

            {/* ==================================================== */}
            {/* User Information */}
            {/* ==================================================== */}

            <Card className="border-[#333] bg-[#222]">

              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-white">
                  <User className="h-5 w-5 text-[#4A9FD4]" />
                  User Information
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-6">

                {/* Name */}

                <div className="space-y-2">
                  <Label className="text-gray-300">
                    Full Name
                  </Label>

                  <Input
                    placeholder="Enter full name"
                    value={formData.name}
                    onChange={(e) =>
                      handleInputChange("name", e.target.value)
                    }
                    className="border-[#333] bg-[#1B1B1B] text-white focus:border-[#2563EB]"
                  />

                  {errors.name && (
                    <p className="text-sm text-red-500">
                      {errors.name}
                    </p>
                  )}
                </div>

                {/* Email */}

                <div className="space-y-2">
                  <Label className="text-gray-300">
                    Email Address
                  </Label>

                  <Input
                    type="email"
                    placeholder="example@company.com"
                    value={formData.email}
                    onChange={(e) =>
                      handleInputChange("email", e.target.value)
                    }
                    className="border-[#333] bg-[#1B1B1B] text-white focus:border-[#2563EB]"
                  />

                  {errors.email && (
                    <p className="text-sm text-red-500">
                      {errors.email}
                    </p>
                  )}
                </div>

                {/* Role */}

                <div className="space-y-2">

                  <Label className="text-gray-300">
                    Role
                  </Label>

                  <Select
                    value={formData.role}
                    onValueChange={(value) =>
                      handleInputChange("role", value)
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1B1B1B] text-white">
                      <SelectValue />
                    </SelectTrigger>

                    <SelectContent className="border-[#333] bg-[#222] text-white">

                      <SelectItem value="ADMIN">
                        Administrator
                      </SelectItem>

                      <SelectItem value="USER">
                        User
                      </SelectItem>

                      <SelectItem value="OPERATOR">
                        Operator
                      </SelectItem>

                    </SelectContent>

                  </Select>

                </div>

                {/* Status */}

                <div className="space-y-2">

                  <Label className="text-gray-300">
                    Status
                  </Label>

                  <Select
                    value={formData.status}
                    onValueChange={(value) =>
                      handleInputChange("status", value)
                    }
                  >
                    <SelectTrigger className="border-[#333] bg-[#1B1B1B] text-white">
                      <SelectValue />
                    </SelectTrigger>

                    <SelectContent className="border-[#333] bg-[#222] text-white">

                      <SelectItem value="ACTIVE">
                        Active
                      </SelectItem>

                      <SelectItem value="INACTIVE">
                        Inactive
                      </SelectItem>

                    </SelectContent>

                  </Select>

                </div>

              </CardContent>

            </Card>
                        {/* ==================================================== */}
            {/* Security */}
            {/* ==================================================== */}

            <Card className="border-[#333] bg-[#222]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-white">
                  <Lock className="h-5 w-5 text-[#4A9FD4]" />
                  Security
                </CardTitle>
              </CardHeader>

              <CardContent className="space-y-6">

                {/* Password */}

                <div className="space-y-2">
                  <Label className="text-gray-300">
                    Password
                  </Label>

                  <div className="relative">
                    <Input
                      type={showPassword ? "text" : "password"}
                      placeholder="Enter password"
                      value={formData.password}
                      onChange={(e) =>
                        handleInputChange(
                          "password",
                          e.target.value
                        )
                      }
                      className="border-[#333] bg-[#1B1B1B] pr-12 text-white focus:border-[#2563EB]"
                    />

                    <button
                      type="button"
                      onClick={() =>
                        setShowPassword(!showPassword)
                      }
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 transition hover:text-white"
                    >
                      {showPassword ? (
                        <EyeOff className="h-5 w-5" />
                      ) : (
                        <Eye className="h-5 w-5" />
                      )}
                    </button>
                  </div>

                  {errors.password && (
                    <p className="text-sm text-red-500">
                      {errors.password}
                    </p>
                  )}
                </div>

                {/* Confirm Password */}

                <div className="space-y-2">
                  <Label className="text-gray-300">
                    Confirm Password
                  </Label>

                  <div className="relative">
                    <Input
                      type={
                        showConfirmPassword
                          ? "text"
                          : "password"
                      }
                      placeholder="Confirm password"
                      value={formData.confirmPassword}
                      onChange={(e) =>
                        handleInputChange(
                          "confirmPassword",
                          e.target.value
                        )
                      }
                      className="border-[#333] bg-[#1B1B1B] pr-12 text-white focus:border-[#2563EB]"
                    />

                    <button
                      type="button"
                      onClick={() =>
                        setShowConfirmPassword(
                          !showConfirmPassword
                        )
                      }
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 transition hover:text-white"
                    >
                      {showConfirmPassword ? (
                        <EyeOff className="h-5 w-5" />
                      ) : (
                        <Eye className="h-5 w-5" />
                      )}
                    </button>
                  </div>

                  {errors.confirmPassword && (
                    <p className="text-sm text-red-500">
                      {errors.confirmPassword}
                    </p>
                  )}
                </div>

                {/* Password Requirements */}

                <div className="rounded-lg border border-[#333] bg-[#1B1B1B] p-4">

                  <h4 className="mb-3 text-sm font-semibold text-[#4A9FD4]">
                    Password Requirements
                  </h4>

                  <div className="space-y-2 text-sm text-gray-400">

                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          formData.password.length >= 8
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      Minimum 8 characters
                    </div>

                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          /[A-Z]/.test(formData.password)
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      One uppercase letter
                    </div>

                    <div className="flex items-center gap-2">
                      <CheckCircle2
                        className={`h-4 w-4 ${
                          /[0-9]/.test(formData.password)
                            ? "text-green-500"
                            : "text-gray-600"
                        }`}
                      />
                      One number
                    </div>

                  </div>

                </div>

                {/* Force Password Reset */}

                <div className="flex items-center space-x-3 rounded-lg border border-[#333] bg-[#1B1B1B] p-4">

                  <Checkbox
                    checked={formData.forcePasswordReset}
                    onCheckedChange={(checked) =>
                      handleInputChange(
                        "forcePasswordReset",
                        checked === true
                      )
                    }
                  />

                  <div>
                    <Label className="cursor-pointer text-white">
                      Require password change on first login
                    </Label>

                    <p className="mt-1 text-sm text-gray-400">
                      User will be asked to create a new password
                      after logging in for the first time.
                    </p>
                  </div>

                </div>

              </CardContent>
            </Card>

          </div>

          {/* Bottom Buttons */}

          <div className="mt-8 flex justify-end gap-3 border-t border-[#333] pt-6">

            <Button
              type="button"
              variant="outline"
              onClick={() => router.push("/users")}
              className="border-[#444] bg-transparent text-white hover:bg-[#333]"
            >
              Cancel
            </Button>

            <Button
              type="submit"
              disabled={loading}
              className="gap-2 bg-[#2563EB] text-white hover:bg-[#1D4ED8]"
            >
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Creating User...
                </>
              ) : (
                <>
                  <Save className="h-4 w-4" />
                  Create User
                </>
              )}
            </Button>

          </div>

        </form>

      </div>
    </div>
  );
}